"use client";
import type { RefObject } from "react";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisNavbarContent } from "./components/navbar/content";
import View0 from "./components/navbar/variants/01-pill-groups";
import View1 from "./components/navbar/variants/02-mega-menu";
import View2 from "./components/navbar/variants/03-morph";
import View3 from "./components/navbar/variants/04-feature-morph";
import View4 from "./components/navbar/variants/05-expand";
import View5 from "./components/navbar/variants/06-simple";
const variants = {"pill-groups":View0,"mega-menu":View1,"morph":View2,"feature-morph":View3,"expand":View4,"simple":View5};
export type { ArtemisNavbarColumn, ArtemisNavbarContent, ArtemisNavbarLink, ArtemisNavbarMenu, ArtemisNavbarMenuLink } from "./components/navbar/content";
export interface ArtemisNavbarProps { className?: string; scrollContainer?: RefObject<HTMLElement | null>; variant?: "pill-groups" | "mega-menu" | "morph" | "feature-morph" | "expand" | "simple"; /** The words on the navbar; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisNavbarContent>; }
export function ArtemisNavbar({ className, scrollContainer, variant = "pill-groups", content }: ArtemisNavbarProps) {const View = variants[variant];return <ArtemisScope className={`${variant === "expand" || variant === "simple" ? "art:sticky art:top-0 art:z-50" : "art:relative art:z-40"} ${className ?? ""}`}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center">{variant === "expand" ? <View4 scrollContainer={scrollContainer} content={content}/> : variant === "simple" ? <View5 scrollContainer={scrollContainer} content={content}/> : <View content={content}/>}</div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link or button, and where it goes. */
export interface ArtemisNavbarLink {
  label: string;
  href: string;
}

/** A link inside an open menu. */
export interface ArtemisNavbarMenuLink extends ArtemisNavbarLink {
  /** A short line under the label. morph and feature-morph. */
  description?: string;
  /** The card's icon. feature-morph, which keeps its own icon for that slot when you leave this out. */
  icon?: ComponentType<{ className?: string }>;
}

/** A small heading over a list of links, inside an open menu. */
export interface ArtemisNavbarColumn {
  title: string;
  links: ArtemisNavbarLink[];
}

/** A top-level item that opens a menu. */
export interface ArtemisNavbarMenu {
  label: string;
  /** Headed columns of links. pill-groups and mega-menu; morph and feature-morph list their links. */
  columns?: ArtemisNavbarColumn[];
  /** Links, each with an optional description and icon. morph and feature-morph; pill-groups and mega-menu show them as one column when `columns` is left out. feature-morph sets them in a fixed two-by-two panel, so four fill it. */
  links?: ArtemisNavbarMenuLink[];
  /** A highlighted card beside the columns. mega-menu. */
  feature?: { title: string; description: string; href: string };
}

/** The words on an Artemis navbar. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisNavbarContent {
  /** The name beside the logo mark, and where it links. All layouts. */
  brand: ArtemisNavbarLink;
  /** Items that open a menu, shown before `links`. pill-groups, mega-menu, morph and feature-morph. */
  menus?: ArtemisNavbarMenu[];
  /** Plain links in the bar. All layouts. The bars of morph and feature-morph have a fixed width: their own two one-word menus and two links fill them, and more or longer labels wrap or overflow. */
  links: ArtemisNavbarLink[];
  /** The quiet sign-in link. pill-groups, mega-menu, morph and feature-morph. */
  login?: ArtemisNavbarLink;
  /** A sign-up link beside sign-in. pill-groups. */
  signup?: ArtemisNavbarLink;
  /** The main button. All layouts. */
  cta: ArtemisNavbarLink;
  /** A line at the foot of an open menu, beside a link to `cta`. pill-groups and mega-menu. */
  menuNote?: string;
}

"use client";
// @zeus-internal
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { animate, motion, useMotionValue, useReducedMotion, useTransform } from "motion/react";
import { ChevronDown, Menu, X } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { DesktopContent, MobileMenu, defaultMenuNote, defaultMenus } from "./01-pill-groups/content";
import type { ArtemisNavbarContent } from "../content";
const DEFAULT = {
    brand: { label: "Workspace", href: "/" },
    menus: defaultMenus,
    links: [{ label: "Pricing", href: "#pricing" }, { label: "Download", href: "#download" }],
    login: { label: "Log in", href: "#login" },
    signup: { label: "Sign up", href: "#signup" },
    cta: { label: "Book a demo", href: "#demo" },
    menuNote: defaultMenuNote,
} satisfies ArtemisNavbarContent;
export default function NavbarPillGroups({ content }: { content?: Partial<ArtemisNavbarContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const id = useId();
    const reduced = !!useReducedMotion();
    const headerRef = useRef<HTMLElement>(null);
    const linksRef = useRef<HTMLDivElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const panelRef = useRef<HTMLDivElement>(null);
    const toggleRef = useRef<HTMLButtonElement>(null);
    const triggers = useRef<(HTMLButtonElement | null)[]>([]);
    const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
    const [active, setActive] = useState<number | null>(null);
    const [last, setLast] = useState(0);
    const [mobile, setMobile] = useState(false);
    const [geometry, setGeometry] = useState({ top: 12, width: 0, height: 52, content: 281 });
    const open = active !== null && !mobile;
    const height = useMotionValue(0);
    const totalHeight = useTransform(height, value => geometry.height + value);
    const cancel = useCallback(() => { if (timer.current)
        clearTimeout(timer.current); timer.current = null; }, []);
    const choose = useCallback((group: number | null) => { cancel(); if (group !== null)
        setLast(group); setActive(group); }, [cancel]);
    const close = useCallback(() => { cancel(); setActive(null); setMobile(false); }, [cancel]);
    const leave = () => { cancel(); timer.current = setTimeout(() => setActive(null), 80); };
    useLayoutEffect(() => {
        const measure = () => {
            const header = headerRef.current?.getBoundingClientRect();
            const links = linksRef.current?.getBoundingClientRect();
            if (!header || !links)
                return;
            setGeometry({ top: links.top - header.top, width: links.width, height: links.height, content: contentRef.current?.getBoundingClientRect().height ?? 281 });
        };
        measure();
        const observer = new ResizeObserver(measure);
        if (linksRef.current)
            observer.observe(linksRef.current);
        if (contentRef.current)
            observer.observe(contentRef.current);
        window.addEventListener("resize", measure);
        return () => { observer.disconnect(); window.removeEventListener("resize", measure); };
    }, []);
    useEffect(() => {
        const control = animate(height, open ? geometry.content : 0, { duration: reduced ? 0 : 0.25, ease: ARTEMIS_EASE_OUT });
        return () => control.stop();
    }, [open, geometry.content, height, reduced]);
    useEffect(() => {
        const outside = (event: PointerEvent) => { if (event.target instanceof Node && !headerRef.current?.contains(event.target))
            close(); };
        const escape = (event: KeyboardEvent) => {
            if (event.key !== "Escape" || (active === null && !mobile))
                return;
            event.preventDefault();
            if (mobile)
                toggleRef.current?.focus();
            else if (active !== null)
                triggers.current[active]?.focus();
            close();
        };
        document.addEventListener("pointerdown", outside);
        document.addEventListener("keydown", escape);
        return () => { document.removeEventListener("pointerdown", outside); document.removeEventListener("keydown", escape); };
    }, [active, mobile, close]);
    useEffect(() => () => cancel(), [cancel]);
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    return <header ref={headerRef} onMouseEnter={cancel} onMouseLeave={mobile ? undefined : leave} className="art:relative art:z-40 art:w-full art:bg-background art:text-foreground">
          <motion.div aria-hidden="true" className="art:pointer-events-none art:absolute art:left-1/2 art:hidden art:-translate-x-1/2 art:rounded-3xl art:border art:border-border art:bg-background art:@min-[1024px]/artemis:block" style={{ top: geometry.top, width: geometry.width, height: totalHeight }}/>
          <nav aria-label="Primary navigation" className="art:mx-auto art:flex art:min-h-16 art:flex-wrap art:items-center art:gap-x-7 art:px-5 art:@min-[640px]/artemis:px-8 art:max-w-screen-2xl art:py-3 art:@min-[1024px]/artemis:grid art:@min-[1024px]/artemis:grid-cols-[1fr_auto_1fr] art:@min-[1024px]/artemis:gap-4">
            <a href={copy.brand.href} className="art:flex art:items-center art:gap-2 art:rounded-full art:py-3 art:text-xl art:font-medium art:tracking-tight art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers art:size-6" aria-hidden="true">
                <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
                <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
                <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
              </svg>
              {copy.brand.label}
            </a>
            <div className="art:ml-auto art:@min-[768px]/artemis:order-3">
              <div className="art:hidden art:items-center art:whitespace-nowrap art:@min-[1024px]/artemis:flex art:gap-1 art:rounded-full art:bg-muted/60 art:p-1.5">
                <a href={copy.login.href} className="art:rounded-full art:px-2 art:py-2 art:text-sm art:text-muted-foreground art:hover:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-ring">
                  {copy.login.label}
                </a>
                <a href={copy.signup.href} className="art:rounded-full art:px-3 art:py-2 art:text-sm art:outline-none art:hover:text-primary art:focus-visible:ring-2 art:focus-visible:ring-ring">
                  {copy.signup.label}
                </a>
                <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                  {copy.cta.label}
                </motion.a>
              </div>
              <motion.button {...press} ref={toggleRef} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:gap-2 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-10 art:p-0 art:@min-[1024px]/artemis:hidden art:rounded-full" aria-label={mobile ? "Close navigation" : "Open navigation"} aria-expanded={mobile} aria-controls={`${id}-mobile`} tabIndex={0} onClick={() => { choose(null); setMobile(!mobile); }}>
                {mobile ? <X className="art:size-5"/> : <Menu className="art:size-5"/>}
              </motion.button>
            </div>
            <div ref={linksRef} id={`${id}-links`} className="art:relative art:order-2 art:hidden art:items-center art:gap-1 art:whitespace-nowrap art:@min-[1024px]/artemis:flex art:rounded-full art:p-1.5">
              {copy.menus.map((menu, group) => <motion.button {...press} ref={node => { triggers.current[group] = node; }} key={menu.label} type="button" className={`art:select-none art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:bg-transparent art:flex art:min-h-10 art:items-center art:justify-between art:gap-1.5 art:px-3 art:text-sm art:outline-none art:transition-colors art:focus-visible:ring-2 art:focus-visible:ring-ring ${active === group ? "art:hover:text-inherit art:text-foreground" : "art:text-muted-foreground art:hover:text-foreground"} art:rounded-full`} aria-expanded={active === group} aria-controls={`${id}-panel`} tabIndex={0} onMouseEnter={() => choose(group)} onClick={() => choose(active === group ? null : group)} onKeyDown={event => {
                if (event.key !== "ArrowDown")
                    return;
                event.preventDefault();
                choose(group);
                requestAnimationFrame(() => panelRef.current?.querySelector<HTMLAnchorElement>("a")?.focus());
            }}>
                {menu.label}<motion.span aria-hidden="true" animate={{ rotate: active === group ? 180 : 0 }} transition={{ duration: reduced ? 0 : 0.2, ease: "easeOut" }}><ChevronDown className="art:size-3.5"/></motion.span>
              </motion.button>)}
              {copy.links.map(link => <a key={link.label} onMouseEnter={() => choose(null)} onClick={close} href={link.href} className="art:flex art:min-h-10 art:items-center art:rounded-full art:px-3 art:text-sm art:text-muted-foreground art:outline-none art:hover:text-foreground art:focus-visible:ring-2 art:focus-visible:ring-ring">
                {link.label}
              </a>)}
            </div>
          </nav>
          {mobile && <MobileMenu id={id} menus={copy.menus} links={copy.links} signup={copy.signup} login={copy.login} cta={copy.cta} group={active} setGroup={choose} reduced={reduced} close={close}/>}
          <motion.div ref={panelRef} id={`${id}-panel`} aria-hidden={!open} inert={!open} className="art:absolute art:top-full art:hidden art:overflow-hidden art:left-1/2 art:-translate-x-1/2 art:rounded-b-3xl art:@min-[1024px]/artemis:block" style={{ pointerEvents: open ? "auto" : "none", width: geometry.width, top: geometry.top + geometry.height, height, clipPath: "inset(0px 0px 0%)" }}>
            <div ref={contentRef} className="art:max-h-[75vh] art:overflow-y-auto art:border-border art:rounded-b-3xl">
              {copy.menus[last] && <DesktopContent menu={copy.menus[last]} note={copy.menuNote} cta={copy.cta} open={open} reduced={reduced} close={close}/>}
            </div>
          </motion.div>
        </header>;
}

"use client";
// @zeus-internal
import { motion } from "motion/react";
import { ArrowUpRight, ChevronDown } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
import type { ArtemisNavbarColumn, ArtemisNavbarLink, ArtemisNavbarMenu } from "../../content";
export const defaultMenus: ArtemisNavbarMenu[] = [
    { label: "Product", columns: [
        { title: "Workspace", links: [{ label: "Projects", href: "#projects" }, { label: "Documents", href: "#documents" }, { label: "Collaboration", href: "#collaboration" }] },
        { title: "Make it yours", links: [{ label: "Integrations", href: "#integrations" }, { label: "Automations", href: "#automations" }, { label: "Enterprise", href: "#enterprise" }] },
    ] },
    { label: "Resources", columns: [
        { title: "Learn", links: [{ label: "Guides", href: "#guides" }, { label: "Customer stories", href: "#stories" }, { label: "Journal", href: "#journal" }] },
        { title: "Build", links: [{ label: "Documentation", href: "#docs" }, { label: "Templates", href: "#templates" }, { label: "What\u2019s new", href: "#updates" }] },
    ] },
];
export const defaultMenuNote = "A little guidance goes a long way.";
/** A menu's columns, or its plain links as one column. */
export const columnsOf = (menu: ArtemisNavbarMenu): ArtemisNavbarColumn[] => menu.columns ?? [{ title: menu.label, links: menu.links ?? [] }];
export function DesktopContent({ menu, note, cta, open, reduced, close }: {
    menu: ArtemisNavbarMenu;
    note: string;
    cta: ArtemisNavbarLink;
    open: boolean;
    reduced: boolean;
    close: () => void;
}) {
    const reveal = (delay: number) => ({
        initial: { opacity: 0, transform: "translateY(8px)" },
        animate: { opacity: open ? 1 : 0, transform: open ? "translateY(0px)" : "translateY(8px)" },
        transition: { duration: reduced ? 0 : open ? 0.2 : 0.1, delay: reduced || !open ? 0 : delay, ease: ARTEMIS_EASE_OUT },
    });
    return <motion.div className="art:mx-auto art:max-w-7xl art:p-6" initial={{ opacity: 0, transform: "translateY(0px)" }} animate={{ opacity: open ? 1 : 0 }} transition={{ duration: reduced ? 0 : open ? 0.2 : 0.1, delay: reduced || !open ? 0 : 0.035, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:grid art:grid-cols-2 art:gap-x-4 art:gap-y-6" key={menu.label}>
      {columnsOf(menu).map((column, i) => <div key={column.title}>
        <motion.h2 className="art:mb-3 art:font-mono art:text-xs art:uppercase art:tracking-widest art:text-muted-foreground" {...reveal(0.018 + i * 0.0075)}>{column.title}</motion.h2>
        <ul className="art:space-y-1">{column.links.map((link, j) => <motion.li key={link.href} {...reveal(0.027 + i * 0.0075 + j * 0.0054)}>
          <a href={link.href} onClick={close} className="art:-ml-2 art:block art:rounded-lg art:px-2 art:py-2 art:text-sm art:text-muted-foreground art:outline-none art:transition-colors art:hover:text-foreground art:focus-visible:ring-2 art:focus-visible:ring-ring">{link.label}</a>
        </motion.li>)}</ul>
      </div>)}
    </div>
    <motion.div key={`${menu.label}-footer`} className="art:mt-8 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:pt-5" {...reveal(0.042)}>
      <p className="art:text-sm art:text-muted-foreground">{note}</p>
      <a href={cta.href} onClick={close} className="art:flex art:items-center art:gap-2 art:rounded-full art:py-2 art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">{cta.label}<ArrowUpRight className="art:size-4"/></a>
    </motion.div>
  </motion.div>;
}
export function MobileMenu({ id, menus, links, signup, login, cta, group, setGroup, reduced, close }: {
    id: string;
    menus: ArtemisNavbarMenu[];
    links: ArtemisNavbarLink[];
    signup: ArtemisNavbarLink;
    login: ArtemisNavbarLink;
    cta: ArtemisNavbarLink;
    group: number | null;
    setGroup: (group: number | null) => void;
    reduced: boolean;
    close: () => void;
}) {
    const press = { whileHover: reduced ? undefined : { scale: 1.01 }, whileTap: reduced ? undefined : { scale: 0.98 }, transition: ARTEMIS_SPRING_PRESS };
    return <motion.div id={`${id}-mobile`} className="art:absolute art:inset-x-0 art:top-full art:z-50 art:max-h-[70dvh] art:overflow-y-auto art:overscroll-contain art:rounded-b-2xl art:border-b art:border-border art:bg-background art:@min-[1024px]/artemis:hidden" initial={reduced ? false : { opacity: 0, y: -6 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.2, ease: ARTEMIS_EASE_OUT }}>
    <div className="art:divide-y art:divide-border art:px-5">
      {menus.map((menu, value) => <div key={menu.label}>
        <motion.button {...press} type="button" className="art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:flex art:min-h-14 art:w-full art:items-center art:justify-between art:text-base art:font-medium art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:rounded-full" aria-expanded={group === value} aria-controls={`${id}-mobile-${value}`} tabIndex={0} onClick={() => setGroup(group === value ? null : value)}>
          {menu.label}<motion.span aria-hidden="true" animate={{ rotate: group === value ? 180 : 0 }} transition={{ duration: reduced ? 0 : 0.2, ease: "easeOut" }}><ChevronDown className="art:size-4"/></motion.span>
        </motion.button>
        {group === value && <motion.div id={`${id}-mobile-${value}`} className="art:pb-5" initial={reduced ? false : { opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.18, ease: ARTEMIS_EASE_OUT }}>
          <div className="art:grid art:grid-cols-2 art:gap-x-4 art:gap-y-5">{columnsOf(menu).map(column => <div key={column.title}>
            <h2 className="art:mb-2 art:text-xs art:font-medium art:text-muted-foreground">{column.title}</h2>
            <ul>{column.links.map(link => <li key={link.href}><a href={link.href} onClick={close} className="art:-ml-2 art:flex art:min-h-10 art:items-center art:rounded-lg art:px-2 art:py-2 art:text-sm art:leading-5 art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">{link.label}</a></li>)}</ul>
          </div>)}</div>
        </motion.div>}
      </div>)}
      {links.map(link => <div key={link.label}><a href={link.href} onClick={close} className="art:flex art:min-h-14 art:items-center art:rounded-lg art:text-base art:font-medium art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">{link.label}</a></div>)}
    </div>
    <a href={signup.href} onClick={close} className="art:mx-5 art:flex art:min-h-12 art:items-center art:rounded-full art:text-sm art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring">{signup.label}</a>
    <div className="art:sticky art:bottom-0 art:grid art:grid-cols-2 art:gap-3 art:border-t art:border-border art:bg-background art:p-4">
      <motion.a {...press} href={login.href} onClick={close} tabIndex={0} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full">{login.label}</motion.a>
      <motion.a {...press} href={cta.href} onClick={close} tabIndex={0} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full">{cta.label}</motion.a>
    </div>
  </motion.div>;
}

"use client";
// @zeus-internal
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { ChevronDown, Menu, X } from "lucide-react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import { DesktopContent, MobileMenu, defaultMenuNote, defaultMenus } from "./02-mega-menu/content";
import type { ArtemisNavbarContent } from "../content";
const DEFAULT = {
    brand: { label: "Workspace", href: "/" },
    menus: defaultMenus,
    links: [{ label: "Pricing", href: "#pricing" }, { label: "Download", href: "#download" }],
    login: { label: "Log in", href: "#login" },
    cta: { label: "Book a demo", href: "#demo" },
    menuNote: defaultMenuNote,
} satisfies ArtemisNavbarContent;
export default function NavbarMegaMenu({ content }: { content?: Partial<ArtemisNavbarContent> } = {}) {
