              {copy.links.map((link, index) => <motion.a key={link.label} href={link.href} aria-current={selected === index ? "page" : undefined} className={`art:flex art:min-h-11 art:items-center art:rounded-lg art:px-3 art:font-medium art:text-sm art:outline-none art:transition-colors art:focus-visible:bg-muted ${selected === index ? "art:bg-muted art:text-foreground" : "art:text-muted-foreground art:hover:bg-muted/60 art:hover:text-foreground"}`} initial={reduced ? false : { opacity: 0, y: -4 }} animate={reduced ? { opacity: 1 } : { opacity: 1, y: 0 }} transition={{ duration: reduced ? 0 : 0.18, delay: reduced ? 0 : index * 0.025, ease: ARTEMIS_EASE_OUT }} onClick={() => { setSelected(index); setMobile(false); }}>{link.label}</motion.a>)}
              <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-2 art:w-full art:@min-[640px]/artemis:hidden art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>{copy.cta.label}</motion.a>
            </div>
          </motion.div>}</AnimatePresence>
        </header>;
}

// @zeus-internal
import type { KeyboardEvent } from "react";
export function artemisEscapeDismiss(event: KeyboardEvent<HTMLElement>, close: () => void) {
  if (event.key !== "Escape" || event.defaultPrevented) return;
  const triggers = [...event.currentTarget.querySelectorAll<HTMLButtonElement>('button[aria-expanded="true"]')];
  if (!triggers.length) return;
  const trigger = triggers.find(button => button.getClientRects().length > 0) ?? triggers[0];
  event.preventDefault();
  event.stopPropagation();
  close();
  trigger?.focus();
}
